(int, int) minMax(List<int> list) {
  var min = list.first;
  var max = list.first;
  for (final n in list) {
    if (n < min) min = n;
    if (n > max) max = n;
  }
  return (min, max);
}

void main() {
  final (lo, hi) = minMax([3, 1, 4]);
  print('$lo-$hi');
  var a = 1;
  var b = 2;
  (a, b) = (b, a);
  print('$a $b');
  print(minMax([5]) == (5, 5));
}
